import math


def warmup_cosine(t, lr_max, warmup, total):
    t = min(max(t, 0), total)
    if t < warmup:
        return lr_max * t / warmup
    span = total - warmup
    if span <= 0:
        return lr_max
    return lr_max * (1 - (t - warmup) / span)


def schedule_table(lr_max, warmup, total, ts):
    return [warmup_cosine(t, lr_max, warmup, total) for t in ts]
